import React from 'react';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';

import HikingRadish from './HikingRadish';

const HikingEditAdditional: React.FC = () => {
  const hikingContext = React.useContext(HikingContext);
  if (!hikingContext) return <div>Wrong hiking context</div>;
  return (
    <section className="p-3">
      <HikingRadish id_hiking={hikingContext.id} />
    </section>
  );
};

export default HikingEditAdditional;
