import React from 'react';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import { getHikingStartToFinishDates } from '@apps/Hiking/@helpers/hikingDays.helper';
import {
  addHikingKeyPoint,
  deleteHikingKeyPoint,
  getHikingKeyPoints,
  IHikingKeyPointDTO,
  updateHikingKeyPoint,
} from '@apps/Hiking/@services/hikingKeyPoints.service';
import { RouteObjectType } from '@apps/Routes/@types/routes.types';
import { selectRouteObjectAsync } from '@apps/Routes/RouteObjectSelectModal/routeObjectSelectModalHelper';
import HorizontalScrollable from '@components/HorizontalScrollable';
import MapPoint from '@components/MapPoint';
import PageHeader from '@components/PageHeader';
import notificationHelper from '@helpers/notificationHelper';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';
import { showModal } from '@ui-kit/Modal';

const HikingEditWeather: React.FC = () => {
  const hikingContext = React.useContext(HikingContext);
  const [points, setPoints] = React.useState<IHikingKeyPointDTO[]>([]);
  const [isLoading, setIsLoading] = React.useState(false);
  const [error, setError] = React.useState<Error>();

  React.useEffect(() => {
    const start = async () => {
      try {
        if (!hikingContext?.id) throw new Error('need hiking context first');
        setIsLoading(true);
        const res = await getHikingKeyPoints(hikingContext.id);
        setPoints(res);
      } catch (er) {
        setError(er as Error);
      } finally {
        setIsLoading(false);
      }
    };

    start();
  }, [hikingContext?.id]);

  if (isLoading) return <PohLoader />;
  if (error) return <div>{error.message}</div>;

  const handleAdd = async (date: Date) => {
    if (!hikingContext?.route?.id) return;
    const ro = await selectRouteObjectAsync(hikingContext?.route?.id, 'Выбор точки', {
      allowTracks: false,
      defaultPoints: true,
    });
    if (ro.type === RouteObjectType.Line) {
      throw new Error('Only points allowed');
    }
    const newItem = {
      id: '',
      date: date.toISOString(),
      lat: ro.coordinates[0].toString(),
      lon: ro.coordinates[1].toString(),
      name: ro.name,
    };
    const res = await addHikingKeyPoint(hikingContext.id, newItem);
    setPoints((cur) => [...cur, res]);
    notificationHelper.success('Добавлено');
  };

  const handleRemove = (point: IHikingKeyPointDTO) => {
    hikingContext?.id &&
      deleteHikingKeyPoint(hikingContext.id, point.id).then(() => {
        notificationHelper.success('Удалено');
        setPoints((cur) => cur.filter((r) => r.id !== point.id));
      });
  };

  if (!hikingContext) return null;

  return (
    <section className="p-3">
      <PageHeader title="Точки получения погоды"></PageHeader>
      <HorizontalScrollable>
        <div className="d-flex border-start">
          {getHikingStartToFinishDates(hikingContext).map((d, i) => {
            const items = points.filter(
              (p) => new Date(p.date).toLocaleDateString() === d.toLocaleDateString(),
            );
            const handleDragOver = (e: React.DragEvent) => {
              e.preventDefault();
              e.currentTarget.classList.add('border');
              e.currentTarget.classList.add('border-warning');
              e.currentTarget.classList.add('p-1');
            };
            const handleDragLeave = (e: React.DragEvent) => {
              e.preventDefault();
              e.currentTarget.classList.remove('border');
              e.currentTarget.classList.remove('border-warning');
              e.currentTarget.classList.remove('p-1');
            };
            const handleDrop = async (e: React.DragEvent) => {
              e.preventDefault();
              handleDragLeave(e);
              const id = e.dataTransfer.getData('plain/text');
              const copy = e.dataTransfer.getData('plain/copy');
              const point = points.find((p) => p.id === id);
              if (!point || !hikingContext?.id) return;

              if (copy) {
                addHikingKeyPoint(hikingContext.id, {
                  ...point,
                  date: d.toISOString(),
                  id: '',
                }).then((res) => {
                  setPoints((cur) => [...cur, res]);
                  notificationHelper.success('Добавлено');
                });

                return;
              }

              updateHikingKeyPoint(hikingContext.id, {
                ...point,
                date: d.toISOString(),
              }).then((up) => {
                notificationHelper.success('Обновлено');
                setPoints((cur) => cur.map((r) => (r.id === point.id ? up : r)));
              });
            };

            return (
              <div
                key={i}
                style={{ width: `max-content`, minWidth: 0 }}
                className="border-end p-2 flex-grow-0 flex-shrink-0"
              >
                <header
                  title={d.toLocaleDateString('default', { weekday: 'long' })}
                  className="d-flex align-items-center"
                >
                  <span className="text-muted">
                    {d.toLocaleDateString('default', { weekday: 'short' }).toUpperCase()}
                  </span>
                  &nbsp;
                  <strong>{d.toLocaleDateString()}</strong>
                  <PohButton
                    size={ButtonSize.Small}
                    onClick={() => {
                      handleAdd(d);
                    }}
                    icon={IconsEnum.plus}
                    className="ms-auto"
                  />
                </header>
                <div onDragOver={handleDragOver} onDragLeave={handleDragLeave} onDrop={handleDrop}>
                  {items.length > 0 ? (
                    <PohList
                      data={items.map((p) => {
                        const handleDragStart = (e: React.DragEvent) => {
                          //e.preventDefault();
                          e.dataTransfer.effectAllowed = e.altKey || e.ctrlKey ? 'copy' : 'move';
                          e.dataTransfer.dropEffect = 'move';
                          e.dataTransfer.setData('plain/text', p.id);
                          (e.altKey || e.ctrlKey) && e.dataTransfer.setData('plain/copy', '1');
                          e.currentTarget.classList.add('opacity-1');
                        };

                        const handleDragEnd = (e: React.DragEvent) => {
                          e.currentTarget.classList.remove('opacity-1');
                        };
                        return {
                          key: p.id,
                          draggable: true,
                          onDragStart: handleDragStart,
                          onDragEnd: handleDragEnd,
                          onClick: () => {
                            showModal({
                              children: <MapPoint point={[+p.lat, +p.lon]} height={400} />,
                            });
                          },
                          children: (
                            <div className="m-n2">
                              <strong>{p.name}</strong>

                              <aside className="float-end" onClick={(e) => e.stopPropagation()}>
                                <PohButton
                                  size={ButtonSize.Small}
                                  onClick={() => {
                                    handleRemove(p);
                                  }}
                                  icon={IconsEnum.trash}
                                  className="ms-auto"
                                />
                              </aside>
                            </div>
                          ),
                        };
                      })}
                    />
                  ) : (
                    <Empty height={80}>Пока пусто...</Empty>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </HorizontalScrollable>
    </section>
  );
};

export default HikingEditWeather;
