import React from 'react';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import { getHikingDataAsync } from '@apps/Hiking/@services/hiking.service';
import { getHikingAccessGroupAsync } from '@apps/Hiking/@services/hikingRules.service';
import { HikingAccessGroup } from '@apps/Hiking/@types/hiking.rules';
import { IHikingData } from '@apps/Hiking/@types/hiking.types';
import PageLoader from '@components/PageLoader';
import PohAlert from '@ui-kit/Alert';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohContainer from '@ui-kit/layout/Container';
import PohTabs from '@ui-kit/Tabs';

import { hikingEditTabs } from './hikingEditTabs';

interface IHikingEditPageProps {
  id_hiking: number;
}

// is_guide: boolean;
// is_cook: boolean;
// is_writter: boolean;
// is_financier: boolean;
// is_medic: boolean;
// is_admin: boolean;

const HikingEditPage: React.FC<IHikingEditPageProps> = ({ id_hiking }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [error, setIsError] = React.useState<Error>();
  const [hikingData, setHikingData] = React.useState<IHikingData>();
  const [accessGroup, setAccessGroup] = React.useState(HikingAccessGroup.Readonly);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const hd = await getHikingDataAsync(id_hiking);
        setHikingData(hd);

        const accessGroupRes = await getHikingAccessGroupAsync(id_hiking);
        setAccessGroup(accessGroupRes);
      } catch (e) {
        setIsError(e as Error);
      } finally {
        setIsLoading(false);
      }
    };
    init();
  }, [id_hiking]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (error || !hikingData) {
    return <PohAlert>{error?.message}</PohAlert>;
  }

  return (
    <PohContainer>
      <PohBreadcrumbs
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name },
          { href: `/hiking/${id_hiking}/edit`, text: 'Редактирование', active: true },
        ]}
      />
      <h3 className="mb-3">Редактирование похода &laquo;{hikingData.name}&raquo;</h3>
      <HikingContext.Provider value={hikingData}>
        <PohTabs
          useHash
          tabs={hikingEditTabs.filter((x) => {
            const hasAccess = x.accessGroup.includes(accessGroup);
            return {
              ...x,
              disabled: !hasAccess,
              content: hasAccess ? x.content : null,
            };
          })}
        />
      </HikingContext.Provider>
    </PohContainer>
  );
};

export default HikingEditPage;
