import React from 'react';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import { getBaseHikingFromHikingData } from '@apps/Hiking/@mappers/hiking.mapper';
import {
  deleteWorkoutTarget,
  getWorkoutsTargets,
} from '@apps/Workouts/@services/workoutsTargets.service';
import { IWorkoutTarget } from '@apps/Workouts/@types/workoutsTargets.types';
import WorkoutTargetForm from '@apps/Workouts/components/WorkoutTargets/WorkoutTargetForm';
import WorkoutTargetItem from '@apps/Workouts/components/WorkoutTargets/WorkoutTargetItem';
import PageLoader from '@components/PageLoader';
import { AuthContext } from '@contexts/AuthContext';
import { error, success } from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohList from '@ui-kit/List';
import { confirmModal } from '@ui-kit/Modal';

import { getEmptyWorkoutTarget } from '../../../Workouts/@mappers/workouts.empty';

const HikingEditWorkoutTargets: React.FC = () => {
  const [targets, setTargets] = React.useState<IWorkoutTarget[]>([]);
  const [selectedTarget, setSelectedTarget] = React.useState<IWorkoutTarget | null>(null);
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();

  const hikingContext = React.useContext(HikingContext);
  const authContext = React.useContext(AuthContext);

  React.useEffect(() => {
    const init = async () => {
      try {
        if (!hikingContext) throw new Error('Has no hikingContext');
        const dt = await getWorkoutsTargets({ id_hiking: hikingContext.id });
        setTargets(dt);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    init().catch(error);
  }, [hikingContext?.id]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  if (selectedTarget) {
    return (
      <WorkoutTargetForm
        data={selectedTarget}
        onDelete={async () => {
          if (!selectedTarget?.id) {
            return;
          }
          const accept = await confirmModal('Точно удалить?');
          if (accept && hikingContext) {
            await deleteWorkoutTarget({ id: selectedTarget.id });
            setTargets((cur) => cur.filter((c) => c.id !== selectedTarget.id));
            setSelectedTarget(null);
            success('Удалено');
          }
        }}
        onCancel={() => setSelectedTarget(null)}
        onSave={(updatedTarget) => {
          if (selectedTarget?.id === 0) {
            setTargets((cur) => cur.concat(updatedTarget));
            setSelectedTarget(null);
            return;
          }

          setTargets((cur) => cur.map((c) => (c.id === selectedTarget.id ? updatedTarget : c)));
          setSelectedTarget(null);
        }}
      />
    );
  }

  const handleAdd = () => {
    if (!authContext.user) throw new Error('Who are you?');
    if (!hikingContext) throw new Error('What is you hiking?');
    hikingContext &&
      setSelectedTarget(
        getEmptyWorkoutTarget(authContext.user, getBaseHikingFromHikingData(hikingContext)),
      );
  };

  return (
    <section className="p-3">
      <h5 className="mb-3">
        <PohButton
          variant={ButtonVariant.Success}
          className="float-end"
          size={ButtonSize.Small}
          onClick={handleAdd}
        >
          Добавить Цель
        </PohButton>
        Цели тренировок
      </h5>
      <PohList
        data={targets.map((target) => {
          return {
            key: target.id,
            content: <WorkoutTargetItem data={target} />,
            action: true,
            onClick: () => setSelectedTarget(target),
          };
        })}
      />
    </section>
  );
};

export default HikingEditWorkoutTargets;
