import React from 'react';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import { setHikingFieldAsync } from '@apps/Hiking/@services/hiking.service';
import notificationHelper from '@helpers/notificationHelper';
import PohImageUploader from '@ui-kit/ImageUploader';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

const HikingEditVisual: React.FC = () => {
  const hikingContext = React.useContext(HikingContext);
  if (!hikingContext) return <div>Wrong hiking context</div>;
  return (
    <section className="p-3">
      <PohRow>
        <PohCol sm={2}>
          Аватарка похода <br />
          (рек. 255×255)
        </PohCol>
        <PohCol sm={10}>
          <div style={{ display: 'inline-block', aspectRatio: 1, width: 96 }}>
            <PohImageUploader
              src={hikingContext.visual.photo}
              folder="images/hiking/avatars/"
              width={255}
              height={255}
              sizes={[255]}
              ratio={1}
              validation={{ maxWidth: 4444, maxHeight: 4444, size: 5024288 }}
              onChange={(src) => {
                setHikingFieldAsync(hikingContext.id, 'ava', src)
                  .then(() => notificationHelper.success('Сохранено'))
                  .catch((e) => notificationHelper.error(e));
              }}
            />
          </div>
        </PohCol>
      </PohRow>
      <PohRow className="mt-3">
        <PohCol sm={2}>
          Изображение <br />
          рек. 1590×400
        </PohCol>
        <PohCol sm={10}>
          <div style={{ display: 'inline-block', aspectRatio: 1590 / 400, height: 168 }}>
            <PohImageUploader
              src={hikingContext.visual.bg}
              folder="images/hiking/bg/"
              width={1590}
              height={400}
              sizes={['1590/400']}
              validation={{ maxWidth: 4444, maxHeight: 4444, size: 5024288 }}
              onChange={(src, saveres) => {
                setHikingFieldAsync(
                  hikingContext.id,
                  'bg',
                  (saveres?.sizes as any)['1590/400'] ?? src,
                )
                  .then(() => notificationHelper.success('Сохранено'))
                  .catch((e) => notificationHelper.error(e));
              }}
            />
          </div>
        </PohCol>
      </PohRow>
      <PohRow className="mt-3">
        <PohCol sm={2}>Цвет</PohCol>
        <PohCol sm={10}>
          <PohInput
            type={InputTypes.color}
            defaultValue={hikingContext.visual.color}
            onRealChange={(v) => {
              setHikingFieldAsync(hikingContext.id, 'color', v)
                .then(() => notificationHelper.success('Сохранено'))
                .catch((e) => notificationHelper.error(e));
            }}
          />
        </PohCol>
      </PohRow>{' '}
      <PohRow className="mt-3">
        <PohCol sm={2}>Слоган</PohCol>
        <PohCol sm={10}>
          <PohInput
            defaultValue={hikingContext.slogan ?? ''}
            onRealChange={(v) => {
              setHikingFieldAsync(hikingContext.id, 'slogan', v)
                .then(() => notificationHelper.success('Сохранено'))
                .catch((e) => notificationHelper.error(e));
            }}
            name="slogan"
            autoComplete="slogan"
            placeholder="Введите слоган или девиз"
          />
        </PohCol>
      </PohRow>
    </section>
  );
};

export default HikingEditVisual;
