import React from 'react';

import ArrowReturnRight from '@pohodnik/icons/svg/Arrows/ArrowReturnRight';
import Palette from '@pohodnik/icons/svg/Graphics/Palette';
import BlockquoteLeft from '@pohodnik/icons/svg/Typography/BlockquoteLeft';
import Code from '@pohodnik/icons/svg/Typography/Code';
import CodeSquare from '@pohodnik/icons/svg/Typography/CodeSquare';
import Hr from '@pohodnik/icons/svg/Typography/Hr';
import ListOl from '@pohodnik/icons/svg/Typography/ListOl';
import ListUl from '@pohodnik/icons/svg/Typography/ListUl';
import TextParagraph from '@pohodnik/icons/svg/Typography/TextParagraph';
import TypeBold from '@pohodnik/icons/svg/Typography/TypeBold';
import TypeH2 from '@pohodnik/icons/svg/Typography/TypeH2';
import TypeH3 from '@pohodnik/icons/svg/Typography/TypeH3';
import TypeItalic from '@pohodnik/icons/svg/Typography/TypeItalic';
import TypeStrikethrough from '@pohodnik/icons/svg/Typography/TypeStrikethrough';
import Backspace from '@pohodnik/icons/svg/UI/Backspace';
import BackspaceReverse from '@pohodnik/icons/svg/UI/BackspaceReverse';
import Link45Deg from '@pohodnik/icons/svg/UI/Link45Deg';
import { useCurrentEditor } from '@tiptap/react';

import PohButton from '@ui-kit/Button';

interface IWysiwygMenuBarProps {
  children?: React.ReactNode;
}

const WysiwygMenuBar: React.FC<IWysiwygMenuBarProps> = () => {
  const { editor } = useCurrentEditor();
  if (!editor) {
    return null;
  }
  const setLink = React.useCallback(() => {
    const previousUrl = editor.getAttributes('link').href;
    const url = window.prompt('URL', previousUrl);

    // cancelled
    if (url === null) {
      return;
    }

    // empty
    if (url === '') {
      editor.chain().focus().extendMarkRange('link').unsetLink().run();

      return;
    }

    // update link
    editor.chain().focus().extendMarkRange('link').setLink({ href: url }).run();
  }, [editor]);

  return (
    <>
      <PohButton
        icon={true}
        onClick={() => editor.chain().focus().toggleBold().run()}
        disabled={!editor.can().chain().focus().toggleBold().run()}
        active={editor.isActive('bold')}
      >
        <TypeBold />
      </PohButton>
      <PohButton
        icon={true}
        onClick={() => editor.chain().focus().toggleItalic().run()}
        disabled={!editor.can().chain().focus().toggleItalic().run()}
        active={editor.isActive('italic')}
      >
        <TypeItalic />
      </PohButton>
      <PohButton
        icon={true}
        onClick={() => editor.chain().focus().toggleStrike().run()}
        disabled={!editor.can().chain().focus().toggleStrike().run()}
        active={editor.isActive('strike')}
      >
        <TypeStrikethrough />
      </PohButton>
      <PohButton
        icon={true}
        onClick={() => editor.chain().focus().toggleCode().run()}
        disabled={!editor.can().chain().focus().toggleCode().run()}
        active={editor.isActive('code')}
      >
        <Code />
      </PohButton>
      <PohButton
        icon={true}
        onClick={() => editor.chain().focus().setParagraph().run()}
        active={editor.isActive('paragraph')}
      >
        <TextParagraph />
      </PohButton>
      <PohButton
        icon={true}
        onClick={() => editor.chain().focus().toggleHeading({ level: 2 }).run()}
        active={editor.isActive('heading', { level: 2 })}
      >
        <TypeH2 />
      </PohButton>
      <PohButton
        icon={true}
        onClick={() => editor.chain().focus().toggleHeading({ level: 3 }).run()}
        active={editor.isActive('heading', { level: 3 })}
      >
        <TypeH3 />
      </PohButton>

      <PohButton
        icon={true}
        onClick={() => editor.chain().focus().toggleBulletList().run()}
        active={editor.isActive('bulletList')}
      >
        <ListUl />
      </PohButton>
      <PohButton
        icon={true}
        onClick={() => editor.chain().focus().toggleOrderedList().run()}
        active={editor.isActive('orderedList')}
      >
        <ListOl />
      </PohButton>
      <PohButton
        icon={true}
        onClick={() => editor.chain().focus().toggleCodeBlock().run()}
        active={editor.isActive('codeBlock')}
      >
        <CodeSquare />
      </PohButton>
      <PohButton
        icon={true}
        onClick={() => editor.chain().focus().toggleBlockquote().run()}
        active={editor.isActive('blockquote')}
      >
        <BlockquoteLeft />
      </PohButton>
      <PohButton icon={true} onClick={() => editor.chain().focus().setHorizontalRule().run()}>
        <Hr />
      </PohButton>
      <PohButton icon={true} onClick={() => editor.chain().focus().setHardBreak().run()}>
        <ArrowReturnRight />
      </PohButton>
      <PohButton
        icon={true}
        onClick={() => editor.chain().focus().undo().run()}
        disabled={!editor.can().chain().focus().undo().run()}
      >
        <Backspace />
      </PohButton>
      <PohButton
        icon={true}
        onClick={() => editor.chain().focus().redo().run()}
        disabled={!editor.can().chain().focus().redo().run()}
      >
        <BackspaceReverse />
      </PohButton>
      <PohButton
        icon={true}
        onClick={() => editor.chain().focus().setColor('#fe4542').run()}
        active={editor.isActive('textStyle', { color: '#fe4542' })}
      >
        <Palette style={{ color: '#fe4542' }} />
      </PohButton>

      <PohButton
        icon={true}
        title={editor.isActive('link') ? 'Ctrl+Click to unset link' : ''}
        onClick={(e) => (e.ctrlKey ? editor.chain().focus().unsetLink().run() : setLink())}
        active={editor.isActive('link')}
      >
        <Link45Deg />
      </PohButton>
    </>
  );
};

export default WysiwygMenuBar;
