import React from 'react';

import { Color } from '@tiptap/extension-color';
import Link from '@tiptap/extension-link';
import ListItem from '@tiptap/extension-list-item';
import Placeholder from '@tiptap/extension-placeholder';
import TextStyle from '@tiptap/extension-text-style';
import { EditorProvider } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';

import styles from './styles.module.less';
import WysiwygMenuBar from './WysiwygMenuBar';

interface IWysiwygEditorProps {
  html: string;
  onChange: (html: string) => void;
  placeholder?: string;
}

const WysiwygEditor: React.FC<IWysiwygEditorProps> = ({ html, onChange, placeholder }) => {
  const extensions = [
    Color.configure({ types: [TextStyle.name, ListItem.name] }),
    TextStyle.configure({}),
    StarterKit.configure({
      bulletList: {
        keepMarks: true,
        keepAttributes: false, // TODO : Making this as `false` becase marks are not preserved when I try to preserve attrs, awaiting a bit of help
      },
      orderedList: {
        keepMarks: true,
        keepAttributes: false, // TODO : Making this as `false` becase marks are not preserved when I try to preserve attrs, awaiting a bit of help
      },
    }),
    Link.configure({
      HTMLAttributes: {
        // Change rel to different value
        // Allow search engines to follow links(remove nofollow)
        rel: 'noopener noreferrer',
        // Remove target entirely so links open in current tab
        target: '_blank',
      },
    }),
  ];

  if (placeholder) {
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    extensions.push(Placeholder.configure({ placeholder }));
  }

  return (
    <section className={styles.wysiwygEditor}>
      <EditorProvider
        slotBefore={<WysiwygMenuBar />}
        extensions={extensions}
        content={html}
        onUpdate={({ editor }) => {
          const content = editor.getHTML();
          onChange(content);
        }}
      />
    </section>
  );
};

export default WysiwygEditor;
