import React from 'react';

import clsx from 'clsx';

import { IHikingScheduleItem } from '@apps/Hiking/@types/hiking.baseTypes';

import styles from './styles.module.less';

interface IScheduleItemDraggableProps extends React.HTMLAttributes<HTMLDivElement> {
  item: IHikingScheduleItem;
  date: Date;
  onChangeItem?: (up: Partial<Pick<IHikingScheduleItem, 'start' | 'finish'>>) => void;
}

const ScheduleItemDraggable: React.FC<IScheduleItemDraggableProps> = ({
  item,
  date,
  onChangeItem,
  ...rest
}) => {
  const startOfDay = new Date(date.getFullYear(), date.getMonth(), date.getDate(), 0, 0, 0, 0);
  const endOfDay = new Date(date.getFullYear(), date.getMonth(), date.getDate(), 23, 59, 59, 999);

  const start = item.start <= startOfDay ? startOfDay : item.start;
  const finish = item.finish >= endOfDay ? endOfDay : item.finish;

  const divRef = React.useRef<HTMLDivElement>(null);
  const topResizerRef = React.useRef<HTMLDivElement>(null);
  const bottomResizerRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    if (!divRef.current || !topResizerRef.current || !bottomResizerRef.current) return;

    const element = divRef.current;
    let isResizing = false;
    let startY = 0;
    let startHeight = 0;
    let startTop = 0;

    let startEl: HTMLDivElement;

    const onMouseMove = (e: MouseEvent) => {
      if (!isResizing) return;

      const deltaY = e.clientY - startY;

      if (topResizerRef.current?.contains(e.target as Node)) {
        // Ресайз сверху
        const newHeight = Math.max(15, startHeight - deltaY);
        const newTop = startTop + deltaY;

        element.style.height = `${newHeight}px`;
        element.style.top = `${newTop}px`;

        (e.target as HTMLDivElement).dataset.time = new Date(
          startOfDay.getTime() + newTop * 60000,
        ).toLocaleTimeString();
      } else if (bottomResizerRef.current?.contains(e.target as Node)) {
        // Ресайз снизу
        const newHeight = Math.max(15, startHeight + deltaY);
        element.style.height = `${newHeight}px`;
        (e.target as HTMLDivElement).dataset.time = new Date(
          startOfDay.getTime() + (startTop + newHeight) * 60000,
        ).toLocaleTimeString();
      }
    };

    const onMouseUp = () => {
      isResizing = false;
      document.body.style.userSelect = '';
      document.body.style.cursor = '';

      if (startEl.dataset.type === 'start') {
        const [h = 0, m = 0] = (startEl.dataset.time ?? '').split(':').map(Number);
        onChangeItem?.({ start: new Date(item.start.setHours(h, m, 0, 0)) });
      } else if (startEl.dataset.type === 'finish') {
        const [h = 23, m = 59] = (startEl.dataset.time ?? '').split(':').map(Number);
        onChangeItem?.({ finish: new Date(item.finish.setHours(h, m, 0, 0)) });
      }
      startEl.dataset.time = '';
      startEl.dataset.type = '';

      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
    };

    const onMouseDown = (e: MouseEvent, _isTop: boolean) => {
      e.preventDefault();
      e.stopPropagation();

      isResizing = true;
      startY = e.clientY;
      startHeight = element.offsetHeight;
      startTop = element.offsetTop;

      startEl = e.target as HTMLDivElement;

      document.body.style.userSelect = 'none';
      document.body.style.cursor = 'row-resize';

      window.addEventListener('mousemove', onMouseMove);
      window.addEventListener('mouseup', onMouseUp);
    };

    topResizerRef.current.addEventListener('mousedown', (e) => onMouseDown(e, true));
    bottomResizerRef.current.addEventListener('mousedown', (e) => onMouseDown(e, false));

    return () => {
      topResizerRef.current?.removeEventListener('mousedown', (e) => onMouseDown(e, true));
      bottomResizerRef.current?.removeEventListener('mousedown', (e) => onMouseDown(e, false));
    };
  }, []);

  return (
    <div
      {...rest}
      draggable
      ref={divRef}
      onDragStart={(e: React.DragEvent) => {
        //e.preventDefault();
        e.dataTransfer.effectAllowed = e.altKey || e.ctrlKey ? 'copy' : 'move';
        e.dataTransfer.dropEffect = 'move';
        e.dataTransfer.setData('plain/text', item.id.toString());
        (e.altKey || e.ctrlKey) && e.dataTransfer.setData('plain/copy', '1');
        e.currentTarget.classList.add(styles.dragged);
      }}
      onDragEnd={(e) => {
        e.currentTarget.classList.remove(styles.dragged);
      }}
      style={{
        position: 'absolute',
        width: '100%',
        left: 0,
        top: start.getHours() * 60 + start.getMinutes(),
        height: (finish.getTime() - start.getTime()) / 60000,
      }}
      className={clsx(
        styles.scheduleItem,
        item.finish > endOfDay && styles.hasNoFinish,
        item.start < startOfDay && styles.hasNoStart,
        rest.className,
        item.foodAct?.id && styles[`dayEventEat${item.foodAct?.id}`],
        item.routeObject?.distance && styles.dayEventWalk,
      )}
    >
      <div
        ref={topResizerRef}
        onClick={(e) => {
          e.preventDefault();
          e.stopPropagation();
        }}
        draggable
        onDragStart={(e) => {
          e.preventDefault();
          e.stopPropagation();
        }}
        className={styles.topResize}
        data-type="start"
      />
      {item.finish >= endOfDay && item.start <= startOfDay ? '*' : item.name}
      <div
        ref={bottomResizerRef}
        onClick={(e) => {
          e.preventDefault();
          e.stopPropagation();
        }}
        data-type="finish"
        draggable
        onDragStart={(e) => {
          e.preventDefault();
          e.stopPropagation();
        }}
        className={styles.bottomResize}
      />
    </div>
  );
};

export default ScheduleItemDraggable;
